import {
  RestaurantListItemProps,
  default as RestaurantListItem,
} from "@/core/components/primitives/restaurant-list-item/restaurant-list-item";

import AdListItem, { Props as AdListItemProps } from "@/core/components/primitives/ad-list-item/ad-list-item";

import BaseListGroupRenderer, {
  BaseListGroupRendererProps,
  ListGroup,
} from "../base-list-group-renderer/base-list-group-renderer";

export type Restaurant = RestaurantListItemProps & {
  id: string;
  type: "restaurant";
};

export type AdListItem = AdListItemProps & {
  id: string;
  type: "ad";
};

export type RestaurantGroup<T = object> = ListGroup<(Restaurant & T) | (AdListItem & T)>;

export function RestaurantListRenderer<T>({
  data,
  isExpandableList,
  className,
}: Omit<BaseListGroupRendererProps<(Restaurant & T) | (AdListItem & T)>, "renderItem">) {
  return (
    <BaseListGroupRenderer
      data={data}
      isExpandableList={isExpandableList}
      renderItem={(restaurantCardProps) => {
        if (restaurantCardProps.type === "ad") {
          return <AdListItem key={restaurantCardProps.id} {...restaurantCardProps} />;
        }
        return <RestaurantListItem key={restaurantCardProps.id} {...restaurantCardProps} />;
      }}
      className={className}
    />
  );
}
