import { ListReceiverProps, ListTransformerProps } from "@/core/components/blocks/list-block/list-block";
import React, { useEffect, useRef, useState } from "react";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import FullPageOverlay from "@/core/components/primitives/full-page-overlay/full-page-overlay";
import SearchBox, { LabelType, SearchBoxLabel } from "@/core/components/modules/search-box/search-box";

import styles from "./restaurant-tag-filterer.module.less";
import CheckboxButtons from "@/core/components/primitives/checkbox-buttons/checkbox-buttons";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { AnimatePresence, motion } from "framer-motion";
import { IconName } from "@/core/components/primitives/icon/icon";
import { useHashState } from "../../../../hooks";
import { useTranslation } from "react-i18next";
import EventAggregator from "@/core/helpers/event-aggregator";
import { multipleClassNames } from "@/core/helpers";

const labels: LabelType = "Restaurant";

type Tag = {
  id: string;
  title: string;
};

type TagGroup<T> = {
  id: string;
  title: string;
  tags: Array<T>;
};

type Data = {
  listObjects: Array<{
    tags: Array<Tag>;
  }>;
};

type Props = ListTransformerProps<Data> & {
  blockIds: Array<string>;
  filterTagGroups: Array<TagGroup<Tag>>;
  quickFilters: Array<Tag>;
  filterHeadline: string;
  filterParagraph: RichTextType;
};

const RestaurantTagFilterer = ({
  blockIds,
  filterTagGroups,
  quickFilters,
  data,
  children,
  filterHeadline,
  filterParagraph,
}: Props) => {
  const [showFiltersOverlay, setShowFiltersOverlay] = useState<boolean>(false);

  const stickyBottomRef = useRef<HTMLDivElement>(null);
  const [stickyBottomHeight, setStickyBottomHeight] = useState(0);

  const searchAndFilterRef = useRef<HTMLDivElement>(null);
  const [searchAndFilterWidth, setSearchAndFilterWidth] = useState(0);

  const [hashState, setHashState] = useHashState(["filter", "quickFilter"]);
  const selectedQuickFilter = hashState.quickFilter[0];

  const { t } = useTranslation();

  const _setSearchAndFilterWidth = () => {
    if (searchAndFilterRef.current) {
      setSearchAndFilterWidth(searchAndFilterRef.current.offsetWidth);
    }
  };

  useEffect(() => {
    const { remove } = EventAggregator.subscribe("onResizeWindowWidth", _setSearchAndFilterWidth);
    _setSearchAndFilterWidth();

    return () => {
      remove();
    };
  }, []);

  useEffect(() => {
    if (stickyBottomRef.current) {
      setStickyBottomHeight(stickyBottomRef.current.offsetHeight);
    }
  }, [showFiltersOverlay]);

  const filterTagGroupsWithSelected = filterTagGroups.map((group) => ({
    ...group,
    tags: group.tags.map((tag) => ({ ...tag, isChecked: hashState.filter.includes(tag.id) })),
  }));

  const allActiveFilters = [...hashState.filter, ...(selectedQuickFilter ? [selectedQuickFilter] : [])];
  const checkedTags = filterTagGroupsWithSelected.flatMap((group) => group.tags).filter((tag) => tag.isChecked);

  const filteredData = data
    .map((group) => {
      const listObjects = group.listObjects.filter(({ tags }) => {
        //Return true if no filters are selected or false if the not _all_ the selected filters are present in the tags of the object
        if (allActiveFilters.length === 0) {
          return true;
        }
        return allActiveFilters.every((tagId) => (tags ?? []).some((tag) => tag.id === tagId));
      });
      return { ...group, listObjects };
    })
    .filter((gr) => gr.listObjects.length > 0);

  const amountOfHits = filteredData.reduce((acc, curr) => acc + curr.listObjects.length, 0);

  return (
    <>
      <div className={styles.wrapper}>
        <SearchBoxLabel labels={labels} />
        <div className={styles.searchAndFilterWrapper} ref={searchAndFilterRef}>
          <SearchBox
            blockIds={blockIds}
            labels={labels}
            queryCreator={(item) =>
              `title:${item}^100 title:*${item}*^30 title:${item}~1 keywords:${item}^50 keywords:*${item}*^20 name:${item}^35 name:*${item}*^10`
            }
            searchResultWidth={searchAndFilterWidth}
          />
          <PrimaryButton
            iconLeftNew={hashState.filter.length > 0 ? undefined : "filter-list"}
            label={t("restaurantFilterButtonWithActiveFilters", { count: hashState.filter.length })}
            onClick={() => setShowFiltersOverlay(true)}
            className={styles.filterButton}
          />
        </div>
        <div className={styles.quickFilterWrapper}>
          {quickFilters
            .map((tag) => ({
              ...tag,
              icon: mapTagToIcon(tag),
              isSelected: selectedQuickFilter === tag.id,
            }))
            .filter((tagWithMaybeIcon) => tagWithMaybeIcon.icon !== undefined)
            .map((tagExtraData) => (
              <div key={tagExtraData.id} className={styles.quickFilter}>
                <PrimaryButton
                  iconCenterNew={tagExtraData.icon}
                  size="large"
                  onClick={() => {
                    //If the quick filter is already selected, deselect it on click
                    if (tagExtraData.isSelected) {
                      setHashState({
                        filter: hashState.filter,
                        quickFilter: [],
                      });
                      return;
                    }

                    setHashState({
                      filter: hashState.filter,
                      quickFilter: [tagExtraData.id],
                    });
                  }}
                  className={tagExtraData.isSelected ? styles.selectedQuickFilter : undefined}
                />
                <p className={multipleClassNames("body-xxs", tagExtraData.isSelected && "bold")}>
                  {tagExtraData.title}
                </p>
              </div>
            ))}
        </div>
        {filteredData.length === 0 && (
          <div className={styles.noResultWrapper}>
            <h2>{t("restaurantFilterNoResultHeadline")}</h2>
            {checkedTags.length > 0 && (
              <CheckboxButtons
                options={checkedTags.map((tag) => ({ value: tag.id, label: tag.title }))}
                onOptionClick={(clickedTagId) => {
                  const newFilter = hashState.filter.filter((id) => id !== clickedTagId);
                  setHashState({
                    filter: newFilter,
                    quickFilter: hashState.quickFilter,
                  });
                }}
                value={checkedTags
                  .filter((tag) => tag.isChecked)
                  .map((tag) => tag.id)
                  .join(", ")}
              />
            )}
            <PrimaryButton
              label={t("restaurantFilterNoResultClearFilters")}
              isFullWidth={true}
              onClick={() => {
                setHashState({
                  filter: [],
                  quickFilter: [],
                });
              }}
            />
          </div>
        )}
      </div>
      <FullPageOverlay open={showFiltersOverlay} onClose={() => setShowFiltersOverlay(false)}>
        <div className={styles.overlayContentWrapper}>
          <FilterPage
            filterTagGroups={filterTagGroupsWithSelected}
            onTagClick={(tagId) => {
              const didHashStateContainTag = hashState.filter?.includes(tagId);

              const newFilter = didHashStateContainTag
                ? hashState.filter.filter((id) => id !== tagId) //Toggle off the tag
                : [...hashState.filter, tagId];

              setHashState({
                filter: newFilter,
                quickFilter: hashState.quickFilter,
              });
            }}
            headline={filterHeadline}
            paragraph={filterParagraph}
            marginBottom={stickyBottomHeight}
          />
          <motion.div
            ref={stickyBottomRef}
            initial={{ bottom: `${-stickyBottomHeight}px` }}
            animate={{ bottom: 0 }}
            exit={{ bottom: `${-stickyBottomHeight}px` }}
            transition={{ duration: 0.4, ease: "easeOut" }}
            className={styles.stickyBottom}
          >
            <div className={styles.resultAmount}>
              <p className="bold">{t("restaurantFilterNumberOfHits")}&nbsp;</p>
              <AnimatePresence>
                <motion.p
                  key={amountOfHits}
                  initial={{ x: 300, opacity: 0 }}
                  animate={{ y: 0, x: 0, opacity: 1 }}
                  exit={{ y: 30, opacity: 0, transition: { duration: 0.5 } }}
                  transition={{ duration: 0.7 }}
                  className="bold"
                >
                  {amountOfHits}
                </motion.p>
              </AnimatePresence>
            </div>
            <OutlineButton
              iconLeftNew="close"
              label={t("restaurantFilterClearFilter")}
              onClick={() => {
                setHashState({
                  filter: [],
                  quickFilter: hashState.quickFilter,
                });
              }}
              isFullWidth={true}
            />
            <PrimaryButton
              label={t("restaurantFilterDoFilter")}
              onClick={() => setShowFiltersOverlay(false)}
              isFullWidth={true}
            />
          </motion.div>
        </div>
      </FullPageOverlay>

      {React.Children.map(children, (child) => {
        if (!React.isValidElement<ListReceiverProps<Data>>(child)) {
          return child;
        }
        return React.cloneElement(child, { data: filteredData });
      })}
    </>
  );
};

type FilterPageProps = {
  filterTagGroups: Array<TagGroup<Tag & { isChecked: boolean }>>;
  onTagClick: (tagId: string) => void;
  headline: string;
  paragraph: RichTextType;
  marginBottom?: number;
};

const FilterPage = ({ filterTagGroups, onTagClick, headline, paragraph, marginBottom }: FilterPageProps) => {
  const { t } = useTranslation();
  return (
    <div className={styles.filterPageWrapper}>
      <h4>{headline}</h4>
      <div className={styles.paragraphWrapper}>
        <RichText richText={paragraph} />
      </div>
      {filterTagGroups.map((group) => (
        <div key={group.id}>
          <div className={`body-l ${styles.filterGroupTitle}`}>
            {group.title} <p className="body-xs">{`(${t("restaurantFilterChooseMany")})`}</p>
          </div>
          <div>
            <CheckboxButtons
              options={group.tags.map((tag) => ({ value: tag.id, label: tag.title }))}
              onOptionClick={onTagClick}
              value={group.tags
                .filter((tag) => tag.isChecked)
                .map((tag) => tag.id)
                .join(", ")}
            />
          </div>
        </div>
      ))}
    </div>
  );
};

/**Currently these are hardcoded since it would be to complicated to set up so that Tags had Icons in Contentful */
//TODO. Also map from english tag titles
const mapTagToIcon = (tag: Tag): IconName | undefined => {
  switch (tag.title.trim().toLowerCase()) {
    case "event":
      return "ferriswheel";
    case "beställ online":
    case "beställ från mobilen":
    case "preorder":
    case "order online":
      return "mobile";
    case "boka bord":
    case "bordsbokning":
    case "reserve a table":
      return "dining";
    case "parkmat":
    case "snabbmat":
    case "fast food":
      return "fastfood";
    case "restauranger":
    case "restaurants":
      return "restaurant";
    default:
      return undefined;
  }
};

export default RestaurantTagFilterer;
